import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Img,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type JobTransitionProps = Record<string, any>;

const JobTransition: React.FC<JobTransitionProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 5,
  job1Title = "Junior Developer",
  job2Title = "Senior Engineer",
  job1Image = "https://cdn.jsdelivr.net/gh/remotion-dev/brand/symbol/remotion_symbol.png",
  job2Image = "https://cdn.jsdelivr.net/gh/remotion-dev/brand/symbol/remotion_symbol.png",
  lineColor = "#38bdf8",
  textColor = "#ffffff",
  iconSize = 120,
  lineWidth = 6,
}) => {
  useFontLoader(["Poppins", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color handling
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout Constants
  const leftX = width * 0.25;
  const rightX = width * 0.75;
  const centerY = height * 0.45;
  const distance = rightX - leftX;
  const textOffsetY = iconSize / 2 + 40;

  // Animation Config
  const entranceDelay = 5;
  const lineStartFrame = 15;
  const secondIconDelay = 35;

  // 1. Icon 1 Pop In
  const icon1Scale = spring({
    frame: frame - entranceDelay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // 2. Line Drawing
  const lineProgress = interpolate(
    frame,
    [lineStartFrame, lineStartFrame + 30],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. Icon 2 Pop In
  const icon2Scale = spring({
    frame: frame - secondIconDelay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  // 4. Text Fade In & Slide Up
  const textOpacity = interpolate(
    frame,
    [secondIconDelay, secondIconDelay + 20],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const textSlide = interpolate(
    frame,
    [secondIconDelay, secondIconDelay + 20],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Styles
  const iconStyle: React.CSSProperties = {
    width: iconSize,
    height: iconSize,
    borderRadius: "50%",
    backgroundColor: "#190808",
    objectFit: "contain",
    border: `4px solid ${lineColor}`,
    position: "absolute",
    top: centerY - iconSize / 2,
    zIndex: 10,
    boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
    transition: "none", // Required rule
  };

  const textContainerStyle: React.CSSProperties = {
    position: "absolute",
    top: centerY + textOffsetY,
    width: iconSize * 2.5, // Allow text to be wider than icon
    textAlign: "center",
    display: "flex",
    flexDirection: "column",
    gap: 8,
    opacity: textOpacity,
    transform: `translateY(${textSlide}px)`,
    transition: "none", // Required rule
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Poppins, sans-serif" }}>
      
      {/* Connecting Line (SVG Layer) */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, zIndex: 1 }}
      >
        <line
          x1={leftX}
          y1={centerY}
          x2={rightX}
          y2={centerY}
          stroke={lineColor}
          strokeWidth={lineWidth}
          strokeLinecap="round"
          strokeDasharray={distance}
          strokeDashoffset={distance * (1 - lineProgress)}
        />
        
        {/* Animated Arrow Head (Optional detail following the line) */}
        {lineProgress > 0 && lineProgress < 1 && (
             <circle 
                cx={leftX + (distance * lineProgress)} 
                cy={centerY} 
                r={lineWidth * 1.5} 
                fill={lineColor} 
             />
        )}
      </svg>

      {/* Icon 1 */}
      <div
        style={{
          ...iconStyle,
          left: leftX - iconSize / 2,
          transform: `scale(${icon1Scale})`,
        }}
      >
        <Img 
            src={job1Image} 
            style={{ width: "100%", height: "100%", borderRadius: "50%", padding: "15%" }} 
        />
      </div>

      {/* Text 1 */}
      <div
        style={{
          ...textContainerStyle,
          left: leftX - (iconSize * 2.5) / 2,
          // Text 1 appears earlier
          opacity: interpolate(frame, [entranceDelay, entranceDelay + 20], [0, 1], { extrapolateRight: "clamp" }),
          transform: `translateY(${interpolate(frame, [entranceDelay, entranceDelay + 20], [20, 0], { extrapolateRight: "clamp" })}px)`,
        }}
      >
        <span style={{ color: textColor, fontWeight: 700, fontSize: 24 }}>
            {job1Title}
        </span>
      </div>

      {/* Icon 2 */}
      <div
        style={{
          ...iconStyle,
          left: rightX - iconSize / 2,
          transform: `scale(${icon2Scale})`,
        }}
      >
        <Img 
            src={job2Image} 
            style={{ width: "100%", height: "100%", borderRadius: "50%", padding: "15%" }} 
        />
      </div>

       {/* Text 2 */}
       <div
        style={{
          ...textContainerStyle,
          left: rightX - (iconSize * 2.5) / 2,
        }}
      >
        <span style={{ color: textColor, fontWeight: 700, fontSize: 24 }}>
            {job2Title}
        </span>
      </div>

    </AbsoluteFill>
  );
};

export default JobTransition;